// Parse Task Pack frontmatter and content
const content = $input.first().binary?.data?.data;
let text = '';
if (content) {
  text = Buffer.from(content, 'base64').toString('utf8');
} else {
  text = $input.first().json?.data || '';
}

// Extract YAML frontmatter
const frontmatterMatch = text.match(/^---\n([\s\S]*?)\n---/);
let frontmatter = {};
if (frontmatterMatch) {
  const yaml = frontmatterMatch[1];
  // Simple YAML parsing
  yaml.split('\n').forEach(line => {
    const [key, ...valueParts] = line.split(':');
    if (key && valueParts.length) {
      frontmatter[key.trim()] = valueParts.join(':').trim();
    }
  });
}

// Extract sections
const sections = {
  task_id: frontmatter.task_id || 'UNKNOWN',
  role: frontmatter.role || $input.first().json?.role,
  status: frontmatter.status || 'READY',
  raw_content: text,
  allowed_inputs: [],
  deliverables: [],
  constraints: [],
  acceptance_checklist: []
};

// Extract Allowed Inputs
const inputsMatch = text.match(/## Allowed Inputs\n([\s\S]*?)(?=##|$)/);
if (inputsMatch) {
  sections.allowed_inputs = inputsMatch[1].trim().split('\n').filter(l => l.startsWith('- ')).map(l => l.replace('- ', ''));
}

// Extract Deliverables
const deliverablesMatch = text.match(/## Deliverables\n([\s\S]*?)(?=##|$)/);
if (deliverablesMatch) {
  sections.deliverables = deliverablesMatch[1].trim().split('\n').filter(l => l.startsWith('- ')).map(l => l.replace('- ', ''));
}

return { json: { ...sections, project_root: $input.first().json?.project_root, task_pack_path: $input.first().json?.task_pack_path } };

// Build minimal context for AI execution
const data = $input.first().json;
const allowedInputs = data.allowed_inputs || [];
const deliverables = data.deliverables || [];

// Build the prompt for AI
const prompt = `
# Task Execution

## Current Role: ${data.role}
## Task ID: ${data.task_id}

## Task Pack Content:
${data.raw_content}

## Instructions:
1. Read only the Allowed Inputs listed in the task pack
2. Produce exactly the Deliverables specified
3. Follow all constraints
4. Output a receipt in the standard format

## Output Format:
【完成内容】
- ...
【输出文件】
- ...
【自检】
- [ ] ...
【风险与未完成】
- ...
`;

return {
  json: {
    prompt,
    task_id: data.task_id,
    role: data.role,
    project_root: data.project_root,
    allowed_inputs: allowedInputs,
    deliverables: deliverables
  }
};

// Validate output
const output = $input.first().json?.text || $input.first().json?.message?.content || '';
const taskId = $('Build Minimal Context').first().json?.task_id;
const deliverables = $('Build Minimal Context').first().json?.deliverables || [];

const validations = [];

// Check if receipt format is present
const hasReceipt = output.includes('【完成内容】') && output.includes('【输出文件】');
validations.push({ name: 'receipt_format', passed: hasReceipt, message: hasReceipt ? 'Receipt format correct' : 'Missing receipt format' });

// Check if self-check is present
const hasSelfCheck = output.includes('【自检】');
validations.push({ name: 'self_check', passed: hasSelfCheck, message: hasSelfCheck ? 'Self-check present' : 'Missing self-check' });

const allPassed = validations.every(v => v.passed);

return {
  json: {
    task_id: taskId,
    output,
    validations,
    all_passed: allPassed,
    status: allPassed ? 'REVIEW' : 'FAILED_VALIDATION'
  }
};

// Mark task as failed validation
const data = $input.first().json;
return {
  json: {
    task_id: data.task_id,
    status: 'FAILED_VALIDATION',
    validations: data.validations,
    output: data.output,
    action_required: 'Fix validation errors and retry'
  }
};

// Mark task as DONE
const taskId = $('Validate Output').first().json?.task_id;
const output = $('Validate Output').first().json?.output;
const reviewNotes = $json['Review Notes'] || '';

return {
  json: {
    task_id: taskId,
    status: 'DONE',
    output: output,
    review_notes: reviewNotes,
    completed_at: new Date().toISOString()
  }
};

// Handle rejection - determine if rework or cancel
const taskId = $('Validate Output').first().json?.task_id;
const decision = $json.Decision;
const reviewNotes = $json['Review Notes'] || '';

const status = decision.includes('Cancel') ? 'CANCELLED' : 'REJECTED_NEEDS_REWORK';

return {
  json: {
    task_id: taskId,
    status: status,
    review_notes: reviewNotes,
    action_required: status === 'CANCELLED' ? 'Task cancelled by reviewer' : 'Fix issues per review notes and retry'
  }
};
